        # Early rounds: extra reward for cooperation to encourage pro-social behavior
        if round_num < 5:
            base += 0.02
        # Late rounds: slightly less generous, we tighten the criteria
        elif round_num > 10:
            base -= 0.02
    else:  # defect
        base = -0.4
        # Early rounds: less harsh penalty (more forgiving)
        if round_num < 5:
            base += 0.02
        # Late rounds: stricter punishment for defection
        elif round_num > 10:
            base -= 0.02

    # Influence of own recent behavior – now using a shorter window (3)
