    if my_history:
        recent = my_history[-recent_window:] if len(my_history) >= recent_window else my_history
        recent_coop = sum(1 for a in recent if a)
        recent_len = len(recent)
        if recent_len > 0:
            recent_coop_rate = recent_coop / recent_len
            # Stronger adjustment for very cooperative or very defective recent self
            if recent_coop_rate > 0.8:
                if observation["action"] == "cooperate":
                    base += 0.05
                else:  # defect
                    base -= -0.05  # less penalty, i.e., add positive to base
